def isi_dari_kode(apps, schema_editor):
    """Rak bertingkat lama (kode dasar + nomor, mis. AT3-1-1 .. AT3-1-4) jadi rak 1 kolom: induk AT3-1, baris 1..4.

    Hanya kalau ada minimal 2 rak dengan kode dasar sama; rak tunggal (R1, TK-02) tidak diubah.
    """
    Rak = apps.get_model("master", "Rak")
    per = {}
    for r in Rak.objects.all():
        m = re.match(r"^(.+?)[-.](\d+)$", r.kode)
        if m:
            per.setdefault(m.group(1), []).append((r, int(m.group(2))))
    for dasar, isi in per.items():
        if len(isi) < 2:
            continue
        for r, t in isi:
            Rak.objects.filter(pk=r.pk).update(induk=dasar, baris=t, kolom=1)



